import { createMiddleware } from '@tanstack/react-start'

// Anonymous visitors have no stored Supabase session, so the (large) Supabase
// client is only downloaded when a session may exist. This keeps it out of the
// initial bundle of every public page.
function mayHaveSession(): boolean {
  if (typeof window === 'undefined') return false
  try {
    // Lovable preview surfaces broker the session from the parent editor frame.
    if (window.parent !== window) return true
    for (let i = 0; i < localStorage.length; i++) {
      const key = localStorage.key(i)
      if (key && key.startsWith('sb-') && key.includes('-auth-token')) return true
    }
    return false
  } catch {
    return true
  }
}

// Must be registered as a global `functionMiddleware` in `src/start.ts`; otherwise
// the browser never attaches the bearer token to serverFn RPCs.
export const attachSupabaseAuth = createMiddleware({ type: 'function' }).client(
  async ({ next }) => {
    if (!mayHaveSession()) return next({ headers: {} })
    const { supabase } = await import('./client')
    const { data } = await supabase.auth.getSession()
    const token = data.session?.access_token
    return next({
      headers: token ? { Authorization: `Bearer ${token}` } : {},
    })
  },
)
